export type SpeakingPackV3 = { topic: string; title: string; part1: string[]; cue: string; points: string[]; part3: string[] };
function pack(topic: string, title: string, interview: string, cue: string, points: string, discussion: string): SpeakingPackV3 {
  return { topic, title, part1: interview.split("|"), cue, points: points.split("|"), part3: discussion.split("|") };
}

